-- Functions
CREATE OR REPLACE FUNCTION public.calculate_prediction_points(prediction_id_input uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  p record;
  m record;
  home_points int := 0;
  away_points int := 0;
  sign_points int := 0;
  total int := 0;
begin
  select * into p
  from public.predictions
  where id = prediction_id_input;

  if p.id is null then
    return 0;
  end if;

  select * into m
  from public.matches
  where id = p.match_id;

  if m.id is null or m.status <> 'finished' then
    return 0;
  end if;

  if p.predicted_home_goals = m.home_goals then
    home_points := 2;
  end if;

  if p.predicted_away_goals = m.away_goals then
    away_points := 2;
  end if;

  if public.match_sign(p.predicted_home_goals, p.predicted_away_goals) = public.match_sign(m.home_goals, m.away_goals) then
    sign_points := 3;
  end if;

  total := home_points + away_points + sign_points;

  insert into public.points (
    league_id,
    user_id,
    match_id,
    prediction_id,
    home_goal_points,
    away_goal_points,
    sign_points,
    total_points,
    calculated_at
  )
  values (
    p.league_id,
    p.user_id,
    p.match_id,
    p.id,
    home_points,
    away_points,
    sign_points,
    total,
    now()
  )
  on conflict (league_id, user_id, match_id)
  do update set
    home_goal_points = excluded.home_goal_points,
    away_goal_points = excluded.away_goal_points,
    sign_points = excluded.sign_points,
    total_points = excluded.total_points,
    calculated_at = now();

  return total;
end;
$function$;

CREATE OR REPLACE FUNCTION public.handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
begin
  insert into public.profiles (
    id,
    full_name
  )
  values (
    new.id,
    coalesce(
      new.raw_user_meta_data->>'full_name',
      split_part(new.email, '@', 1)
    )
  );

  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.join_league_by_code(invite_code_input text)
 RETURNS TABLE(league_id uuid, league_name text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_league_id uuid;
  v_league_name text;
begin
  if v_user_id is null then
    raise exception 'Not authenticated';
  end if;

  select l.id, l.name
    into v_league_id, v_league_name
  from leagues l
  where upper(l.invite_code) = upper(trim(invite_code_input))
  limit 1;

  -- No matching league: return zero rows; the caller treats this as "not found".
  if v_league_id is null then
    return;
  end if;

  if not exists (
    select 1 from league_members lm
    where lm.league_id = v_league_id
      and lm.user_id = v_user_id
  ) then
    insert into league_members (league_id, user_id, role)
    values (v_league_id, v_user_id, 'member');
  end if;

  return query select v_league_id, v_league_name;
end;
$function$;

CREATE OR REPLACE FUNCTION public.lock_predictions_for_started_matches()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
begin
  update public.predictions p
  set lock_status = 'locked', updated_at = now()
  from public.matches m
  where p.match_id = m.id
    and m.kickoff_at <= now()
    and p.lock_status = 'open';
end;
$function$;

CREATE OR REPLACE FUNCTION public.match_sign(home_goals integer, away_goals integer)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select case
    when home_goals = away_goals then 'X'
    when home_goals > away_goals then '1'
    else '2'
  end;
$function$;

CREATE OR REPLACE FUNCTION public.recalculate_points_after_match_update()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
begin
  if new.status = 'finished' then
    perform public.recalculate_points_for_match(new.id);
  end if;

  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.recalculate_points_for_match(match_id_input uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  prediction_record record;
begin
  for prediction_record in
    select id
    from public.predictions
    where match_id = match_id_input
  loop
    perform public.calculate_prediction_points(prediction_record.id);
  end loop;
end;
$function$;

CREATE OR REPLACE FUNCTION public.refresh_leaderboard_for_league(league_id_input uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
begin
  insert into public.leaderboard (
    league_id,
    user_id,
    full_name,
    total_points
  )
  select
    lm.league_id,
    lm.user_id,
    p.full_name,
    coalesce(sum(pt.total_points), 0)
  from public.league_members lm
  left join public.profiles p
    on p.id = lm.user_id
  left join public.points pt
    on pt.league_id = lm.league_id
    and pt.user_id = lm.user_id
  where lm.league_id = league_id_input
  group by lm.league_id, lm.user_id, p.full_name
  on conflict (league_id, user_id)
  do update set
    total_points = excluded.total_points,
    full_name = excluded.full_name;
end;
$function$;

CREATE OR REPLACE FUNCTION public.set_match_result(match_id_input uuid, home_goals_input integer, away_goals_input integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
begin
  update public.matches
  set
    home_goals = home_goals_input,
    away_goals = away_goals_input,
    status = 'finished',
    updated_at = now()
  where id = match_id_input;

  perform public.recalculate_points_for_match(match_id_input);
end;
$function$;

CREATE OR REPLACE FUNCTION public.set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$;

-- Views
create or replace view public.leaderboard as
SELECT lm.league_id,
    lm.user_id,
    COALESCE(pr.full_name, 'Okänd spelare'::text) AS full_name,
    COALESCE(sum(pt.total_points), (0)::bigint) AS total_points
   FROM ((league_members lm
     LEFT JOIN profiles pr ON ((pr.id = lm.user_id)))
     LEFT JOIN points pt ON (((pt.league_id = lm.league_id) AND (pt.user_id = lm.user_id))))
  GROUP BY lm.league_id, lm.user_id, pr.full_name;

-- Triggers
CREATE TRIGGER set_profiles_updated_at BEFORE UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER set_companies_updated_at BEFORE UPDATE ON public.companies FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER set_leagues_updated_at BEFORE UPDATE ON public.leagues FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER set_matches_updated_at BEFORE UPDATE ON public.matches FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER set_predictions_updated_at BEFORE UPDATE ON public.predictions FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER recalculate_points_when_match_finished AFTER UPDATE OF status, home_goals, away_goals ON public.matches FOR EACH ROW EXECUTE FUNCTION recalculate_points_after_match_update();

-- Auth trigger: create a profile row whenever a new auth user signs up.
CREATE TRIGGER on_auth_user_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION handle_new_user();

