-- Policies
create policy "League owners can insert members" on public.league_members
  as permissive
  for insert
  to public
  with check ((EXISTS ( SELECT 1
   FROM leagues l
  WHERE ((l.id = league_members.league_id) AND (l.owner_id = auth.uid())))));

create policy "Users can insert own league membership" on public.league_members
  as permissive
  for insert
  to public
  with check ((user_id = auth.uid()));

create policy "Users can read own league memberships" on public.league_members
  as permissive
  for select
  to public
  using ((user_id = auth.uid()));

create policy "Authenticated users can create leagues" on public.leagues
  as permissive
  for insert
  to authenticated
  with check ((auth.uid() = owner_id));

create policy "League admins can update leagues" on public.leagues
  as permissive
  for update
  to public
  using ((EXISTS ( SELECT 1
   FROM league_members lm
  WHERE ((lm.league_id = leagues.id) AND (lm.user_id = auth.uid()) AND (lm.role = 'admin'::league_member_role)))));

create policy "Users can read leagues by membership" on public.leagues
  as permissive
  for select
  to authenticated
  using ((id IN ( SELECT league_members.league_id
   FROM league_members
  WHERE (league_members.user_id = auth.uid()))));

create policy "Users can read owned leagues" on public.leagues
  as permissive
  for select
  to authenticated
  using ((owner_id = auth.uid()));

create policy "Admin can update matches" on public.matches
  as permissive
  for update
  to authenticated
  using ((lower((auth.jwt() ->> 'email'::text)) = 'rabimasso@hotmail.com'::text))
  with check ((lower((auth.jwt() ->> 'email'::text)) = 'rabimasso@hotmail.com'::text));

create policy "Authenticated users can read matches" on public.matches
  as permissive
  for select
  to authenticated
  using (true);

create policy "Users can read points in their leagues" on public.points
  as permissive
  for select
  to public
  using ((EXISTS ( SELECT 1
   FROM league_members lm
  WHERE ((lm.league_id = points.league_id) AND (lm.user_id = auth.uid())))));

create policy "Users can insert their own predictions" on public.predictions
  as permissive
  for insert
  to public
  with check (((auth.uid() = user_id) AND (EXISTS ( SELECT 1
   FROM league_members lm
  WHERE ((lm.league_id = predictions.league_id) AND (lm.user_id = auth.uid())))) AND (EXISTS ( SELECT 1
   FROM matches m
  WHERE ((m.id = predictions.match_id) AND (m.kickoff_at > now()))))));

create policy "Users can read predictions in their leagues" on public.predictions
  as permissive
  for select
  to public
  using ((EXISTS ( SELECT 1
   FROM league_members lm
  WHERE ((lm.league_id = predictions.league_id) AND (lm.user_id = auth.uid())))));

create policy "Users can update their own unlocked predictions" on public.predictions
  as permissive
  for update
  to public
  using (((auth.uid() = user_id) AND (lock_status = 'open'::prediction_lock_status) AND (EXISTS ( SELECT 1
   FROM matches m
  WHERE ((m.id = predictions.match_id) AND (m.kickoff_at > now()))))));

create policy "Users can insert own profile" on public.profiles
  as permissive
  for insert
  to authenticated
  with check ((auth.uid() = id));

create policy "Users can read their own profile" on public.profiles
  as permissive
  for select
  to public
  using ((auth.uid() = id));

create policy "Users can update their own profile" on public.profiles
  as permissive
  for update
  to public
  using ((auth.uid() = id));

create policy "Authenticated users can read teams" on public.teams
  as permissive
  for select
  to authenticated
  using (true);

create policy "Users can create own tournament predictions" on public.tournament_predictions
  as permissive
  for insert
  to authenticated
  with check ((user_id = auth.uid()));

create policy "Users can insert their own tournament predictions" on public.tournament_predictions
  as permissive
  for insert
  to authenticated
  with check ((auth.uid() = user_id));

create policy "Users can read tournament predictions" on public.tournament_predictions
  as permissive
  for select
  to authenticated
  using (true);

create policy "Users can read tournament predictions in their leagues" on public.tournament_predictions
  as permissive
  for select
  to authenticated
  using (((user_id = auth.uid()) OR (EXISTS ( SELECT 1
   FROM league_members lm
  WHERE ((lm.league_id = tournament_predictions.league_id) AND (lm.user_id = auth.uid()))))));

create policy "Users can update own unlocked tournament predictions" on public.tournament_predictions
  as permissive
  for update
  to authenticated
  using (((user_id = auth.uid()) AND (locked = false)))
  with check (((user_id = auth.uid()) AND (locked = false)));

create policy "Users can update their own tournament predictions" on public.tournament_predictions
  as permissive
  for update
  to authenticated
  using ((auth.uid() = user_id));

create policy "Authenticated users can read tournaments" on public.tournaments
  as permissive
  for select
  to authenticated
  using (true);

